import React from 'react';
import { Link } from 'react-router-dom';
import {
  ArrowLeft,
  Car,
  Home,
  Smartphone,
  Briefcase,
  ShoppingCart,
  Sofa,
  Shirt,
  Dog,
  Bike,
  ShoppingBag,
  User,
} from 'lucide-react';

const categories = [
  { id: 1, name: 'Vehicles', icon: <Car className="w-6 h-6 text-red-500" /> },
  { id: 2, name: 'Properties', icon: <Home className="w-6 h-6 text-red-500" /> },
  { id: 3, name: 'Mobiles & Tablets', icon: <Smartphone className="w-6 h-6 text-red-500" /> },
  { id: 4, name: 'Jobs', icon: <Briefcase className="w-6 h-6 text-red-500" /> },
  { id: 5, name: 'Furniture & Decor', icon: <Sofa className="w-6 h-6 text-red-500" /> },
  { id: 6, name: 'Fashion & Beauty', icon: <Shirt className="w-6 h-6 text-red-500" /> },
  { id: 7, name: 'Hobbies', icon: <Bike className="w-6 h-6 text-red-500" /> },
  { id: 8, name: 'Electronics & Appliances', icon: <ShoppingCart className="w-6 h-6 text-red-500" /> },
  { id: 9, name: 'Pets', icon: <Dog className="w-6 h-6 text-red-500" /> },
  { id: 10, name: 'Businesses & Industrial', icon: <ShoppingBag className="w-6 h-6 text-red-500" /> },
  { id: 11, name: 'Kids & Babies', icon: <ShoppingCart className="w-6 h-6 text-red-500" /> },
  { id: 12, name: 'Services', icon: <User className="w-6 h-6 text-red-500" /> },
];

export default function CategoryPage() {
  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow py-4 flex items-center justify-between px-4">
        {/* Back Arrow */}
        <Link
          to="/"
          className="flex items-center space-x-2 text-gray-700"
          aria-label="Go back"
        >
          <ArrowLeft className="w-6 h-6" />
          <span className="text-sm">Back</span>
        </Link>

        {/* Logo */}
        <Link to="/">
          <img src="/k1.jpeg" alt="Logo" className="w-[100px] h-auto" />
        </Link>
      </header>

      {/* Page Content */}
      <main className="container mx-auto px-4 py-8">
        <h2 className="text-center text-2xl font-bold mb-6">Post Your Ad</h2>
        <p className="text-center text-gray-600 mb-8">Choose a category</p>

        {/* Categories */}
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {categories.map((category) => (
            <button
              key={category.id}
              className="flex items-center justify-between bg-white shadow rounded-md p-4 hover:shadow-lg transition transform hover:-translate-y-1"
            >
              <div className="flex items-center space-x-4">
                {/* Category Icon */}
                <div className="bg-red-100 p-3 rounded-md">{category.icon}</div>
                {/* Category Name */}
                <span className="text-gray-800 font-medium">{category.name}</span>
              </div>
              {/* Forward Arrow */}
              <span className="text-gray-500">&gt;</span>
            </button>
          ))}
        </div>
      </main>
    </div>
  );
}



